def _valid_for_category(cid, nk):
    """Comprueba reglas estrictas de letra/forma para categorias restringidas."""
    if not nk:
        return False
    if cid == "geo-019":
        return nk[0] in "aeiou"
    if cid == "pal-002":
        return nk.startswith("c")
    if cid == "pal-005":
        return nk.endswith("z")
    if cid == "pal-006":
        return nk[0] in ("k", "w")
    if cid == "pal-023":
        return nk.startswith("h")
    if cid == "pal-022":
        return "ñ" in nk
    if cid == "pal-016":
        return nk.startswith("z")
    if cid == "gen-003":
        return nk.startswith("s")
    if cid == "pal-004":
        return (" " not in nk) and (nk == nk[::-1])
    if cid == "pal-003":
        return all(v in nk for v in "aeiou")
    if cid == "pal-007":
        return nk.endswith("ense")
    if cid == "pal-021":
        return (" " not in nk) and nk.endswith(("ar", "er", "ir"))
    return True


def cmd_generar_lote(args):
    """
    python spyle_tool.py generar-lote <salida.json> [--lote 1|2] [--min 405]
    Genera un lote JSON en formato bulk para las 67 categorias de menor densidad del lote indicado.
    """
    out_path = None
    lote_num = 1
    min_target = 405
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--lote" and i + 1 < len(args):
            lote_num = int(args[i + 1])
            i += 2
        elif a == "--min" and i + 1 < len(args):
            min_target = int(args[i + 1])
            i += 2
        elif not a.startswith("--") and out_path is None:
            out_path = a
            i += 1
        else:
            i += 1

    if not out_path:
        print("Uso: python spyle_tool.py generar-lote <salida.json> [--lote 1|2|3|4|5|6] [--min 405]", file=sys.stderr)
        sys.exit(1)

    if lote_num not in (1, 2, 3, 4, 5, 6):
        print(f"[ERROR] Solo estan habilitados --lote 1, 2, 3, 4, 5 o 6 (solicitado: {lote_num}).", file=sys.stderr)
        sys.exit(1)

    prompts_path = locate_prompts_js()
    with open(prompts_path, "r", encoding="utf-8") as f:
        content = f.read()
    if lote_num in (4, 5, 6):
        content, _ = ensure_extra_prompt_categories(content)
    cats, _ = parse_prompts_file(content)

    cats_by_id = {c["id"]: c for c in cats}
    ordered = sorted(cats, key=lambda c: (len(c["pairs"]), c["id"]))
    if lote_num == 4:
        vid_ids = [f"vid-{n:02d}" for n in range(1, 11)]
        target_cats = [cats_by_id[vid] for vid in vid_ids if vid in cats_by_id]
    elif lote_num == 5:
        vid_ids = [f"vid-{n:02d}" for n in range(11, 21)]
        target_cats = [cats_by_id[vid] for vid in vid_ids if vid in cats_by_id]
    elif lote_num == 6:
        vid_ids = [f"vid-{n:02d}" for n in range(21, 31)]
        target_cats = [cats_by_id[vid] for vid in vid_ids if vid in cats_by_id]
    elif lote_num == 3:
        target_cats = [
            c for c in ordered
            if len({normalizar_clave(k) for k, _ in c["pairs"] if normalizar_clave(k)}) < min_target
        ]
    else:
        target_cats = ordered[:67]

    bulk_out = {}
    shortfalls = []

    print(f"\nGenerando Lote {lote_num} ({len(target_cats)} categorias con objetivo >= {min_target} palabras):")
    for idx, c in enumerate(target_cats, start=1):
        cid = c["id"]
        existing = {}
        for rk, rscore in c["pairs"]:
            nk = normalizar_clave(rk)
            if nk and nk not in existing:
                existing[nk] = rscore

        added_buckets = {str(s): [] for s in sorted(VALID_SCORES)}
        queued = set()

        def try_add(word, score_val):
            nk = normalizar_clave(word)
            if not nk or nk in existing or nk in queued:
                return False
            if not _valid_for_category(cid, nk):
                return False
            queued.add(nk)
            added_buckets[str(score_val)].append(nk)
            return True

        for pool in (
            DENSITY_BATCH_1_DATA.get(cid, {}),
            DENSITY_BATCH_1_EXTRA.get(cid, {}),
            DENSITY_BATCH_1_TOPUP.get(cid, {}),
            DENSITY_BATCH_1_FINAL.get(cid, {}),
            DENSITY_BATCH_2_DATA.get(cid, {}),
            DENSITY_BATCH_2_EXTRA.get(cid, {}),
            DENSITY_BATCH_2_TOPUP.get(cid, {}),
            DENSITY_BATCH_2_TOPUP2.get(cid, {}),
            DENSITY_BATCH_2_TOPUP3.get(cid, {}),
            DENSITY_BATCH_2_TOPUP4.get(cid, {}),
            DENSITY_BATCH_3_A.get(cid, {}),
            DENSITY_BATCH_3_B.get(cid, {}),
            DENSITY_BATCH_3_C.get(cid, {}),
            DENSITY_BATCH_3_TOPUP.get(cid, {}),
            DENSITY_VID_1_A.get(cid, {}),
            DENSITY_VID_1_B.get(cid, {}),
            DENSITY_VID_1_TOPUP.get(cid, {}),
            DENSITY_VID_2_A.get(cid, {}),
            DENSITY_VID_2_B.get(cid, {}),
            DENSITY_VID_2_TOPUP.get(cid, {}),
            DENSITY_VID_3_A.get(cid, {}),
            DENSITY_VID_3_B.get(cid, {}),
            DENSITY_VID_3_TOPUP.get(cid, {}),
        ):
            for score_val in (10, 100, 25, 45, 65, 85):
                if score_val in pool:
                    for w in pool[score_val]:
                        try_add(w, score_val)

        # Absorber vocabulario previo compatible desde categorias gen-* de videojuegos
        absorb_map = {"vid-04": ["gen-022"], "vid-05": ["gen-029"]}
        for src_id in absorb_map.get(cid, []):
            src_cat = cats_by_id.get(src_id)
            if src_cat:
                for rk, rscore in src_cat["pairs"]:
                    try_add(rk, rscore)

        # Fallback seguro con variantes validas si aun no alcanza min_target
        if len(existing) + len(queued) < min_target:
            snapshot = list(existing.items())
            for s_str, words_list in added_buckets.items():
                s_val = int(s_str)
                for w in words_list:
                    snapshot.append((w, s_val))
            for rk, rscore in snapshot:
                if len(existing) + len(queued) >= min_target:
                    break
                if cid in STRIP_ARTICLE_ALLOWED:
                    stripped = quitar_articulos_iniciales(rk)
                    if stripped and stripped != rk:
                        try_add(stripped, rscore)
                if cid in NUMBER_VARIANT_ALLOWED:
                    for var in sorted(generar_variantes_numero(rk)):
                        if len(existing) + len(queued) >= min_target:
                            break
                        if var != rk:
                            try_add(var, rscore)

        cat_payload = {k: v for k, v in added_buckets.items() if v}
        if cat_payload:
            bulk_out[cid] = cat_payload

        total_after = len(existing) + len(queued)
        status_mark = "OK" if total_after >= min_target else "FALTA"
        print(f"  {idx:>2}. [{cid}] {len(existing):>3} -> {total_after:>3} (+{len(queued):>3}) [{status_mark}]")
        if total_after < min_target:
            shortfalls.append((cid, total_after, min_target - total_after))

    with open(out_path, "w", encoding="utf-8") as out_f:
        json.dump(bulk_out, out_f, ensure_ascii=False, indent=2)

    print(f"\n[OK] Lote guardado en: {out_path} ({len(bulk_out)} categorias con ampliaciones).")
    if shortfalls:
        print("[ALERTA] Categorias por debajo del objetivo:", shortfalls, file=sys.stderr)
        sys.exit(1)


def main():
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)

    cmd = sys.argv[1].lower()
    args = sys.argv[2:]

    commands = {
        "bulk": cmd_bulk,
        "importar": cmd_importar,
        "sheets": cmd_sheets,
        "auditar": cmd_auditar,
        "normalizar": cmd_normalizar,
        "buscar": cmd_buscar,
        "generar-lote": cmd_generar_lote,
        "consolidar-dias": cmd_consolidar_dias,
        "generar-dias": cmd_consolidar_dias,
    }

    if cmd not in commands:
        print(f"[ERROR] Comando desconocido: '{cmd}'. Comandos validos: {', '.join(commands.keys())}", file=sys.stderr)
        sys.exit(1)

    commands[cmd](args)


if __name__ == "__main__":
    main()
